import {restoreNotifications,collectNotifications,notificationCandidates,unreadCount,notificationSpeech,speechDestination} from './notifications.js';
import {restoreState, dateKey, deviceDefinitions} from './state.js';
const $=id=>document.getElementById(id), storageKey='smart-home-dashboard-v1';
let state;try{state=restoreState(localStorage.getItem(storageKey));}catch{state=restoreState(null);}
const notificationStorageKey='smart-home-notifications-v1';
let inbox;try{inbox=restoreNotifications(localStorage.getItem(notificationStorageKey));}catch{inbox=restoreNotifications(null);}
function persistInbox(){try{localStorage.setItem(notificationStorageKey,JSON.stringify(inbox));}catch{}}
function renderNotifications(){
 const count=unreadCount(inbox),list=$('notification-list');list.replaceChildren();
 $('notification-count').textContent=count?`未読 ${count}件`:'未読なし';
 $('notification-badge').textContent=count>99?'99+':String(count);$('notification-badge').hidden=count===0;
 $('notifications-read-all').disabled=count===0;
 for(const item of inbox.items){
  const row=document.createElement('article');row.className='notification-item'+(item.read?' is-read':'');
  const heading=document.createElement('h3');heading.textContent=item.title;
  const text=document.createElement('p');text.textContent=item.text;
  const time=document.createElement('time');time.dateTime=new Date(item.at).toISOString();time.textContent=new Intl.DateTimeFormat('ja-JP',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(item.at);
  const button=document.createElement('button');button.className='nes-btn';button.textContent=item.read?'確認済み':'確認';button.disabled=item.read;
  button.addEventListener('click',()=>{item.read=true;persistInbox();renderNotifications();if(pageIndex===0)speak();});
  row.append(heading,time,text,button);list.append(row);
 }
 if(!inbox.items.length){const empty=document.createElement('p');empty.className='empty';empty.textContent='通知はありません';list.append(empty);}
}
function syncNotifications(){inbox=collectNotifications(inbox,notificationCandidates(state,dateKey()));persistInbox();renderNotifications();}
let selectedDay=dateKey(),month=new Date(new Date().getFullYear(),new Date().getMonth(),1),toastTimer;
function notify(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
function save(){syncNotifications();try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{notify('保存できませんでした。ブラウザの保存設定を確認してください。');}}
function taskRow(task){const row=document.createElement('div'),label=document.createElement('label'),check=document.createElement('input'),time=document.createElement('time'),title=document.createElement('span'),remove=document.createElement('button');row.className='task'+(task.done?' done':'');check.type='checkbox';check.checked=task.done;check.addEventListener('change',()=>{task.done=check.checked;save();render();});time.textContent=task.time;title.className='title';title.textContent=task.title;remove.className='remove-task';remove.textContent='×';remove.setAttribute('aria-label',task.title+'を削除');remove.addEventListener('click',()=>{if(confirm('「'+task.title+'」を削除しますか？')){state.tasks=state.tasks.filter(t=>t.id!==task.id);save();render();}});label.append(check,time,title);row.append(label,remove);return row;}
function renderTasks(target,day){const tasks=state.tasks.filter(t=>t.date===day).sort((a,b)=>a.time.localeCompare(b.time));target.replaceChildren();tasks.forEach(t=>target.append(taskRow(t)));if(!tasks.length){const empty=document.createElement('p');empty.className='empty';empty.textContent='予定なし';target.append(empty);}return tasks;}
function renderCalendar(){const year=month.getFullYear(),m=month.getMonth();$('month-label').textContent=year+'年 '+(m+1)+'月';$('selected-date').textContent=selectedDay.replaceAll('-',' / ');const grid=$('calendar-grid');grid.replaceChildren();for(let i=0;i<new Date(year,m,1).getDay();i++){const space=document.createElement('span');grid.append(space);}for(let d=1;d<=new Date(year,m+1,0).getDate();d++){const key=dateKey(new Date(year,m,d)),button=document.createElement('button');button.textContent=d;button.className='calendar-day';button.setAttribute('aria-label',key+(state.tasks.some(t=>t.date===key)?' 予定あり':''));button.setAttribute('aria-pressed',String(key===selectedDay));if(key===dateKey()){button.classList.add('today');button.setAttribute('aria-current','date');}if(state.tasks.some(t=>t.date===key))button.classList.add('has-tasks');button.addEventListener('click',()=>{selectedDay=key;renderCalendar();});grid.append(button);}renderTasks($('calendar-tasks'),selectedDay);}
