function deviceIcon(kind,on=true){
 const types={ac:'ac',floor:'floor',light:'ceiling',drop:'humidifier',fan:'fan',air:'purifier',vacuum:'vacuum'};
 const key=types[kind]?types[kind]+(on?'-on':'-off'):kind;
 const holder=document.createElement('template');holder.innerHTML=approvedIconMarkup[key]||approvedIconMarkup.devices;
 return holder.content.firstElementChild;
}
function deviceStatus(definition){const d=state.devices[definition.id];if(!d.on)return 'オフ';return definition.id==='ac'?'冷房 '+d.value+'℃':definition.id==='floor'||definition.id==='ceiling'?d.value+'%':definition.id==='humidifier'?d.value+'%':d.value+'段';}
function renderDevices(){
 const summaries=$('device-summary');summaries.replaceChildren();
 for(const definition of deviceDefinitions){const d=state.devices[definition.id];const row=document.createElement('button'),name=document.createElement('span'),status=document.createElement('strong');row.type='button';row.dataset.device=definition.id;row.setAttribute('aria-haspopup','dialog');row.setAttribute('aria-label',definition.name+'の詳細操作');row.addEventListener('click',()=>openDevice(definition.id));name.textContent=definition.name;status.textContent=deviceStatus(definition);status.id='summary-'+definition.id;row.className=d.on?'device-on':'device-off';const power=document.createElement('span');power.className='power-badge';power.textContent=d.on?'ON':'OFF';row.append(deviceIcon(definition.icon,d.on),name,power,status);summaries.append(row);
 const toggle=$('device-'+definition.id+'-toggle');toggle.setAttribute('aria-checked',String(d.on));$('device-'+definition.id+'-value').value=d.value+definition.unit;const input=$('device-'+definition.id+'-range');input.value=d.value;input.disabled=!d.on;toggle.closest('.appliance-card').classList.toggle('powered',d.on);const oldIcon=toggle.closest('.appliance-card').querySelector('.appliance-top>.pixel-icon');if(oldIcon)oldIcon.replaceWith(deviceIcon(definition.icon,d.on));
 }
 const row=document.createElement('button'),name=document.createElement('span'),status=document.createElement('strong');row.type='button';row.dataset.device='vacuum';row.className=state.vacuum==='running'?'device-on':'device-idle';row.setAttribute('aria-haspopup','dialog');row.setAttribute('aria-label','掃除機の詳細操作');row.addEventListener('click',()=>openDevice('vacuum'));name.textContent='掃除機';status.textContent=({docked:'待機',running:'掃除中',paused:'停止'})[state.vacuum];const power=document.createElement('span');power.className='power-badge';power.textContent=state.vacuum==='running'?'ON':'待機';row.append(deviceIcon('vacuum',state.vacuum==='running'),name,power,status);summaries.append(row);
}
for(const definition of deviceDefinitions){const card=document.createElement('section');card.className='nes-container is-rounded card appliance-card';const top=document.createElement('div');top.className='appliance-top';const name=document.createElement('h2');name.textContent=definition.name;const toggle=document.createElement('button');toggle.className='toggle';toggle.id='device-'+definition.id+'-toggle';toggle.setAttribute('role','switch');toggle.setAttribute('aria-label',definition.name);toggle.append(document.createElement('span'));top.append(deviceIcon(definition.icon),name,toggle);const setting=document.createElement('label');setting.className='appliance-setting';setting.htmlFor='device-'+definition.id+'-range';const text=document.createElement('span');text.textContent=definition.setting;const value=document.createElement('output');value.id='device-'+definition.id+'-value';setting.append(text,value);const input=document.createElement('input');input.type='range';input.id=setting.htmlFor;input.min=definition.min;input.max=definition.max;input.step=1;input.setAttribute('aria-label',definition.name+'の'+definition.setting);toggle.addEventListener('click',()=>{state.devices[definition.id].on=!state.devices[definition.id].on;save();renderDevices();});input.addEventListener('input',()=>{state.devices[definition.id].value=Number(input.value);save();renderDevices();});card.append(top,setting,input);$('appliance-cards').append(card);}
function render(){renderDevices();$('vacuum-status').textContent={docked:'待機',running:'掃除中',paused:'一時停止'}[state.vacuum];$('vacuum-button').textContent=state.vacuum==='running'?'一時停止する':state.vacuum==='paused'?'掃除を再開する':'掃除をはじめる';$('dock-button').hidden=state.vacuum==='docked';document.querySelector('.vacuum').classList.toggle('running',state.vacuum==='running');const today=renderTasks($('task-list'),dateKey());$('task-count').textContent=today.filter(t=>t.done).length+' / '+today.length+' 完了';renderCalendar();}
$('vacuum-button').addEventListener('click',()=>{state.vacuum=state.vacuum==='running'?'paused':'running';render();});$('dock-button').addEventListener('click',()=>{state.vacuum='docked';render();});
function addTask(day){if(state.tasks.length>=100){notify('予定は100件まで追加できます');return;}$('task-date').value=day;$('task-time').value='18:00';$('task-dialog').showModal();$('task-title').focus();}
$('add-task').addEventListener('click',()=>addTask(dateKey()));$('calendar-add').addEventListener('click',()=>addTask(selectedDay));$('close-dialog').addEventListener('click',()=>$('task-dialog').close());$('task-title').addEventListener('input',()=>$('task-title').setCustomValidity(''));
$('task-form').addEventListener('submit',e=>{e.preventDefault();const title=$('task-title').value.trim();if(!title){$('task-title').setCustomValidity('予定を入力してください');$('task-title').reportValidity();return;}state.tasks.push({id:crypto.randomUUID(),title,date:$('task-date').value,time:$('task-time').value,done:false});save();render();$('task-dialog').close();$('task-form').reset();notify('予定を追加しました');});
