const pages=$('pages'),names=['ホーム','家電操作','エンタメ','ニュース','カレンダー','通知'];let pageIndex=0,scrollTimer;
function selectPage(index){pageIndex=Math.max(0,Math.min(names.length-1,index));pages.scrollTo({left:pages.clientWidth*pageIndex,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function updatePage(){pageIndex=Math.round(pages.scrollLeft/pages.clientWidth);document.querySelectorAll('[data-page]').forEach(b=>{if(Number(b.dataset.page)===pageIndex)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('page-position').textContent=names[pageIndex];if(pageIndex===2)refreshMedia();if(pageIndex===0)speak();}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>selectPage(Number(b.dataset.page))));pages.addEventListener('scroll',()=>{clearTimeout(scrollTimer);scrollTimer=setTimeout(updatePage,100);},{passive:true});pages.addEventListener('keydown',e=>{if(e.target!==pages)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();selectPage(pageIndex+(e.key==='ArrowRight'?1:-1));}});window.addEventListener('resize',()=>pages.scrollTo({left:pageIndex*pages.clientWidth,behavior:'instant'}));
document.querySelectorAll('[data-category]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('[data-news-category]').forEach(card=>card.hidden=button.dataset.category!=='all'&&card.dataset.newsCategory!==button.dataset.category);}));
