let lastDay=dateKey();function tick(){const now=new Date();$('clock').textContent=new Intl.DateTimeFormat('ja-JP',{hour:'2-digit',minute:'2-digit',hour12:false}).format(now);$('seconds').textContent=String(now.getSeconds()).padStart(2,'0');$('date').textContent=new Intl.DateTimeFormat('ja-JP',{month:'long',day:'numeric',weekday:'long'}).format(now);if(lastDay!==dateKey(now)){lastDay=dateKey(now);render();}}
render();tick();setInterval(tick,1000);

function formatMediaTime(seconds){
  if(!Number.isFinite(seconds)||seconds<0)return '--:--';
  return `${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;
}
function renderRecord(media){
  const duration=Number.isFinite(media?.duration)&&media.duration>0?media.duration:null;
  const position=duration!==null&&Number.isFinite(media?.position)?Math.max(0,Math.min(duration,media.position)):null;
  $('music-elapsed').textContent=formatMediaTime(position);
  $('music-duration').textContent=formatMediaTime(duration);
  $('music-progress').max=duration||1;$('music-progress').value=position||0;
  $('music-progress').setAttribute('aria-valuetext',duration===null?'再生情報なし':`${formatMediaTime(position)} / ${formatMediaTime(duration)}`);

  $('music-record').classList.toggle('is-playing',media?.status==='available'&&media.playback==='Playing');
  const artwork=$('music-artwork');
  const src=typeof media?.artwork==='string'&&/^data:image\/(jpeg|png);base64,[A-Za-z0-9+/=]+$/.test(media.artwork)?media.artwork:'';
  if(src){if(artwork.getAttribute('src')!==src)artwork.src=src;artwork.hidden=false;}
  else{artwork.hidden=true;artwork.removeAttribute('src');}
  $('music-artwork-fallback').hidden=Boolean(src);
}
$('music-artwork').addEventListener('error',()=>{$('music-artwork').hidden=true;$('music-artwork-fallback').hidden=false;});
let mediaBusy=false;
async function refreshMedia(){
  if(mediaBusy||document.hidden||pageIndex!==2)return;
  mediaBusy=true;$('music-refresh').disabled=true;
  try{
    const response=await fetch('/api/media',{cache:'no-store',signal:AbortSignal.timeout(15000)});
    if(!response.ok)throw Error('media unavailable');
    const media=await response.json();
    renderRecord(media);
    if(media.status==='available'){
      $('music-service').textContent=media.service;
      $('music-title').textContent=media.title||'曲名の情報なし';
      $('music-artist').textContent=media.artist||'';
      $('media-status').textContent=({Playing:'再生中',Paused:'一時停止中',Stopped:'停止中',Closed:'終了',Opened:'待機中',Changing:'切り替え中'})[media.playback]||'再生状態不明';
      $('music-source-label').textContent=media.service;
      $('music-source-note').textContent=media.browser?'ブラウザ経由 · サービス名は判別できません':'Windowsから取得';
    }else{
      $('music-service').textContent='このPCの再生情報';$('music-title').textContent='再生情報なし';$('music-artist').textContent='';
      $('media-status').textContent=media.status==='idle'?'再生なし':media.status==='unsupported'?'Windows PCで利用できます':'取得できません';
      $('music-source-label').textContent='再生元を確認できません';$('music-source-note').textContent='再生元なし';
    }
  }catch{
    renderRecord(null);
    $('music-service').textContent='このPCの再生情報';$('music-title').textContent='再生情報なし';$('music-artist').textContent='';$('media-status').textContent='接続待ち';$('music-source-label').textContent='接続待ち';$('music-source-note').textContent='サーバー再起動待ち';
  }finally{mediaBusy=false;$('music-refresh').disabled=false;}
}
$('music-refresh').addEventListener('click',refreshMedia);
setInterval(refreshMedia,10000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshMedia();});

