let speechTimer,speechIndex=0,speechTarget=null;
function petMessages(){
 const today=state.tasks.filter(task=>task.date===dateKey()&&!task.done).sort((a,b)=>a.time.localeCompare(b.time));
 const messages=[];
 if(today.length)messages.push('今日は「'+today[0].title+'」の日です。'+today[0].time+'からだよ。');
 if(state.devices.humidifier.on)messages.push('加湿器から通知があります。目標湿度は'+state.devices.humidifier.value+'%です。');
 if(state.devices.ac.on)messages.push('エアコンから通知があります。設定温度は'+state.devices.ac.value+'℃です。');
 if(state.vacuum==='running')messages.push('掃除機から通知があります。いま、お掃除中です。');
 if(state.devices.purifier.on)messages.push('空気清浄機から通知があります。空気をきれいにしています。');
 messages.push('今日は、お部屋を整える日にしませんか？');
 return messages;
}
function speak(){
 if(document.hidden||pageIndex!==0)return;
 const messages=petMessages(),message=notificationSpeech(inbox,messages[speechIndex++%messages.length]);
 $('pet-speech-text').textContent=message;
 speechTarget=speechDestination(message);
 const balloon=$('pet-speech');balloon.classList.add('visible');
 balloon.classList.toggle('is-actionable',speechTarget==='calendar');
 if(speechTarget){balloon.setAttribute('role','button');balloon.setAttribute('tabindex','0');balloon.setAttribute('aria-label','予定をカレンダーで確認');}
 else{balloon.setAttribute('role','status');balloon.removeAttribute('tabindex');balloon.removeAttribute('aria-label');}
 clearTimeout(speechTimer);speechTimer=setTimeout(()=>{$('pet-speech').classList.remove('visible');$('pet-speech-text').textContent='';speechTarget=null;$('pet-speech').classList.remove('is-actionable');$('pet-speech').removeAttribute('tabindex');$('pet-speech').setAttribute('role','status');$('pet-speech').removeAttribute('aria-label');},11000);
}
$('pet-speak').addEventListener('click',speak);
function openSpeechTarget(){if(speechTarget!=='calendar'||!$('pet-speech').classList.contains('visible'))return;selectedDay=dateKey();month=new Date(new Date().getFullYear(),new Date().getMonth(),1);renderCalendar();selectPage(4);}
$('pet-speech').addEventListener('click',openSpeechTarget);
$('pet-speech').addEventListener('keydown',event=>{if(speechTarget==='calendar'&&(event.key==='Enter'||event.key===' ')){event.preventDefault();openSpeechTarget();}});
