// Follow the visual viewport, including iPad Safari's changing browser chrome.
function fitViewport(){
 const viewport=window.visualViewport;
 if(viewport&&viewport.scale!==1)return;
 const width=viewport?.width||window.innerWidth,height=viewport?.height||window.innerHeight;
 // Preserve readable controls on small displays while using the entire available aspect ratio.
 const scale=Math.min(1,width/1024,height/768),style=document.documentElement.style;
 style.setProperty('--canvas-scale',scale);
 style.setProperty('--canvas-width',`${width/scale}px`);
 style.setProperty('--canvas-height',`${height/scale}px`);
}
fitViewport();window.addEventListener('resize',fitViewport);window.visualViewport?.addEventListener('resize',fitViewport);
new ResizeObserver(()=>{pages.scrollTo({left:pageIndex*pages.clientWidth,behavior:'instant'});}).observe(pages);
